import{_ as e,o as s,c as t,a2 as i}from"./chunks/framework.DCVnL8g5.js";const g=JSON.parse('{"title":"Versionado y artefactos","description":"","frontmatter":{},"headers":[],"relativePath":"devops/cicd/03-versionado-y-artefactos.md","filePath":"devops/cicd/03-versionado-y-artefactos.md","lastUpdated":1789040978000,"isDraft":false}'),o={name:"devops/cicd/03-versionado-y-artefactos.md"};function n(r,a,l,d,p,c){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="versionado-y-artefactos" tabindex="-1">Versionado y artefactos <a class="header-anchor" href="#versionado-y-artefactos" aria-label="Permalink to &quot;Versionado y artefactos&quot;">​</a></h1><p>Un pipeline maduro produce <strong>artefactos versionados</strong> e <strong>inmutables</strong>. El mismo artefacto validado en staging es el que llega a produccion, identificado por un tag o digest claro.</p><h2 id="versionado-semantico-semver" tabindex="-1">Versionado semantico (SemVer) <a class="header-anchor" href="#versionado-semantico-semver" aria-label="Permalink to &quot;Versionado semantico (SemVer)&quot;">​</a></h2><p>Formato: <code>MAJOR.MINOR.PATCH</code></p><table tabindex="0"><thead><tr><th>Incremento</th><th>Cuando</th></tr></thead><tbody><tr><td><strong>MAJOR</strong></td><td>Cambios incompatibles de API</td></tr><tr><td><strong>MINOR</strong></td><td>Funcionalidad nueva compatible</td></tr><tr><td><strong>PATCH</strong></td><td>Correcciones compatibles</td></tr></tbody></table><p>Ejemplo: <code>2.4.1</code></p><p>En CI/CD:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git tag v2.4.1 -&gt; pipeline build -&gt; imagen myapp:2.4.1 + myapp:2.4.1-abc123f</span></span></code></pre></div><h2 id="tags-y-releases" tabindex="-1">Tags y releases <a class="header-anchor" href="#tags-y-releases" aria-label="Permalink to &quot;Tags y releases&quot;">​</a></h2><p>Flujo habitual:</p><ol><li>Merge a <code>main</code> con version bump en <code>package.json</code> / <code>pyproject.toml</code>.</li><li>Tag anotado: <code>git tag -a v2.4.1 -m &quot;Release 2.4.1&quot;</code>.</li><li>Push tag dispara pipeline de release.</li><li>Publicar notas en GitHub Releases.</li></ol><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  push</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;v*&#39;</span></span></code></pre></div><h2 id="artefactos-inmutables" tabindex="-1">Artefactos inmutables <a class="header-anchor" href="#artefactos-inmutables" aria-label="Permalink to &quot;Artefactos inmutables&quot;">​</a></h2><p>Un artefacto <strong>no se reescribe</strong>. Si hay un bug, publicas <code>2.4.2</code>, no sobrescribes <code>2.4.1</code>.</p><p>Tipos comunes:</p><table tabindex="0"><thead><tr><th>Artefacto</th><th>Ejemplo de identificador</th></tr></thead><tbody><tr><td>Imagen Docker</td><td><code>registry.io/app:2.4.1@sha256:abc...</code></td></tr><tr><td>JAR / wheel</td><td><code>myapp-2.4.1.jar</code></td></tr><tr><td>Frontend estático</td><td><code>dist-2.4.1.zip</code></td></tr><tr><td>Helm chart</td><td><code>app-2.4.1.tgz</code></td></tr></tbody></table><p>Prefiere <strong>digest</strong> ademas de tag para imagenes criticas:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp@sha256:deadbeef...</span></span></code></pre></div><h2 id="build-una-vez-desplegar-muchas" tabindex="-1">Build una vez, desplegar muchas <a class="header-anchor" href="#build-una-vez-desplegar-muchas" aria-label="Permalink to &quot;Build una vez, desplegar muchas&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CI build -&gt; artefacto v2.4.1-abc123f</span></span>
<span class="line"><span>              |</span></span>
<span class="line"><span>              +-&gt; deploy staging (abc123f)</span></span>
<span class="line"><span>              +-&gt; deploy prod     (abc123f)  # mismo binario</span></span></code></pre></div><p>Evita recompilar en el job de produccion.</p><h2 id="metadata-del-artefacto" tabindex="-1">Metadata del artefacto <a class="header-anchor" href="#metadata-del-artefacto" aria-label="Permalink to &quot;Metadata del artefacto&quot;">​</a></h2><p>Adjunta metadata en OCI labels o manifiesto:</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LABEL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> org.opencontainers.image.revision=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${GIT_SHA}&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LABEL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> org.opencontainers.image.version=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${VERSION}&quot;</span></span></code></pre></div><p>En runtime o dashboard sabes que commit esta desplegado.</p><h2 id="registro-de-artefactos" tabindex="-1">Registro de artefactos <a class="header-anchor" href="#registro-de-artefactos" aria-label="Permalink to &quot;Registro de artefactos&quot;">​</a></h2><ul><li><strong>Container:</strong> ECR, GCR, ACR, Docker Hub, GitHub Container Registry.</li><li><strong>Paquetes:</strong> npm, PyPI, Maven (con <code>npm publish</code> solo tras gates).</li><li><strong>Genericos:</strong> GitHub Actions Artifacts (temporal), S3, Artifactory.</li></ul><p>Retencion: define politica (ej. mantener ultimos 30 tags, borrar snapshots de PR a los 7 dias).</p><h2 id="versionado-en-monorepos" tabindex="-1">Versionado en monorepos <a class="header-anchor" href="#versionado-en-monorepos" aria-label="Permalink to &quot;Versionado en monorepos&quot;">​</a></h2><p>Opciones:</p><ul><li><strong>Version unica</strong> del repo (simple, todo se release junto).</li><li><strong>Version por paquete</strong> (Lerna, Changesets, Nx).</li><li><strong>Conventional Commits</strong> + bot que calcula bump automatico.</li></ul><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feat(api): ... -&gt; MINOR</span></span>
<span class="line"><span>fix(web): ...   -&gt; PATCH</span></span>
<span class="line"><span>feat(api)!: ... -&gt; MAJOR (breaking)</span></span></code></pre></div><h2 id="sbom-y-provenance" tabindex="-1">SBOM y provenance <a class="header-anchor" href="#sbom-y-provenance" aria-label="Permalink to &quot;SBOM y provenance&quot;">​</a></h2><p>Para seguridad y compliance:</p><ul><li>Generar <strong>SBOM</strong> (Software Bill of Materials) en build.</li><li>Firmar artefactos (Sigstore, cosign).</li><li>GitHub attestations / SLSA niveles segun madurez.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cosign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry.io/myapp:2.4.1</span></span></code></pre></div><h2 id="buenas-practicas" tabindex="-1">Buenas practicas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas practicas&quot;">​</a></h2><ul><li>Nunca desplegar <code>latest</code> en produccion.</li><li>Tag de git alineado con version de artefacto.</li><li>Changelog humano por release.</li><li>Bloquear deploy si el artefacto no paso staging.</li><li>Documentar como hacer hotfix (<code>2.4.2</code> desde <code>release/2.4</code>).</li></ul><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Rebuild en prod con codigo distinto al validado.</li><li>Tags movidos (<code>git push --force</code> en tags).</li><li>Artefactos de PR mezclados con releases.</li><li>Sin retencion (registro lleno o costes altos).</li><li>Version en codigo desincronizada del tag git.</li></ul><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>El <a href="./04-estrategias-de-despliegue">capitulo 4</a> compara rolling, blue-green, canary y feature flags.</p>`,42)])])}const u=e(o,[["render",n]]);export{g as __pageData,u as default};
